}

/* Partner-Pin: kräftiger als vorher */
.so-hero__pin-partner {
  cursor: pointer;
  transition: transform 0.18s;
  transform-origin: center;
  transform-box: fill-box;
}
.so-hero__pin-partner:hover { transform: scale(1.25); }

/* Tooltip */
.so-hero__tooltip {
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.18s ease;
}
.so-hero__tooltip--active { opacity: 1; }

/* Pulse DORMED (jetzt rot) */
.so-hero__pin-dormed-aura {
  animation: so-pin-pulse 2.6s ease-in-out infinite;
  transform-origin: center;
  transform-box: fill-box;
}
@keyframes so-pin-pulse {
  0%, 100% { opacity: 0.32; transform: scale(1); }
  50%      { opacity: 0.12; transform: scale(1.4); }
}

.so-hero__float-stats {
  position: absolute; inset: 0; pointer-events: none; z-index: 2;
}
.so-hero__fstat {
  position: absolute; background: #fff; border: 1px solid rgba(9,58,126,0.1);
