  else { window.addEventListener('load', trigger); }

  var tooltip = document.getElementById('so-tooltip');
  var ttText  = document.getElementById('so-tt-text');
  var ttRect  = document.getElementById('so-tt-rect');

  function showTooltip(group) {
    var label = group.getAttribute('data-tooltip');
    if (!label || !tooltip) return;
    ttText.textContent = label;
    setTimeout(function() {
      try {
        var bbox = ttText.getBBox();
        var pad = 10;
        var w = Math.max(bbox.width + pad * 2, 40);
        ttRect.setAttribute('x', -w / 2);
        ttRect.setAttribute('width', w);
      } catch(e) {}
    }, 0);
    var pin = group.querySelector('.so-hero__pin-partner');
    if (!pin) return;
    var cx = parseFloat(pin.getAttribute('cx'));
    var cy = parseFloat(pin.getAttribute('cy'));
    tooltip.setAttribute('transform', 'translate(' + cx + ',' + cy + ')');
    tooltip.classList.add('so-hero__tooltip--active');
  }

  function hideTooltip() {
    if (tooltip) tooltip.classList.remove('so-hero__tooltip--active');
  }

  document.querySelectorAll('.so-hero__partner-group').forEach(function(g) {
    g.addEventListener('mouseenter', function() { showTooltip(g); });
    g.addEventListener('mouseleave', function() { hideTooltip(); });
    g.addEventListener('click', function(e) {
      e.stopPropagation();
      showTooltip(g);
    });
  });

  document.addEventListener('click', function(e) {
    if (!e.target.closest('.so-hero__partner-group')) {
      hideTooltip();
    }
  });
})();
</script></div></div></div></div></div></div></div></section></div>
