<script>
(function() {
  var singles = ['so-w-il','so-w-ir'];
  var valsWrap = document.getElementById('so-w-vals');

  var obs = new IntersectionObserver(function(entries) {
    entries.forEach(function(e) {
      if (!e.isIntersecting) return;
      if (e.target.id === 'so-w-vals') {
        e.target.querySelectorAll('.so-what__value').forEach(function(v) {
          v.classList.add('so-what__vis');
        });
      } else {
        e.target.classList.add('so-what__vis');
      }
      obs.unobserve(e.target);
    });
  }, { threshold: 0.1, rootMargin: '0px 0px -30px 0px' });

  singles.forEach(function(id) {
    var el = document.getElementById(id);
    if (el) obs.observe(el);
  });
  if (valsWrap) obs.observe(valsWrap);
})();
</script>
