<script>
(function() {
  var header  = document.getElementById('so-st-hdr');
  var primary = document.getElementById('so-st-prim');
  var second  = document.getElementById('so-st-sec');

  var obs = new IntersectionObserver(function(entries) {
    entries.forEach(function(e) {
      if (!e.isIntersecting) return;
      var id = e.target.id;
      if (id === 'so-st-prim') {
        e.target.querySelectorAll('.so-stats__stat').forEach(function(el) {
          el.classList.add('so-stats__vis');
        });
      } else if (id === 'so-st-sec') {
        e.target.querySelectorAll('.so-stats__context').forEach(function(el) {
          el.classList.add('so-stats__vis');
        });
      } else {
        e.target.classList.add('so-stats__vis');
      }
      obs.unobserve(e.target);
    });
  }, { threshold: 0.1, rootMargin: '0px 0px -30px 0px' });

  [header, primary, second].forEach(function(el) { if (el) obs.observe(el); });
})();
</script>

