<script>
(function() {
  var singles = ['so-snt-txt','so-snt-vis','so-snt-sh'];
  var stepsWrap = document.getElementById('so-snt-steps');

  var obs = new IntersectionObserver(function(entries) {
    entries.forEach(function(e) {
      if (!e.isIntersecting) return;
      if (e.target.id === 'so-snt-steps') {
        e.target.querySelectorAll('.so-snt__step').forEach(function(s) {
          s.classList.add('so-snt__vis');
        });
      } else {
        e.target.classList.add('so-snt__vis');
      }
      obs.unobserve(e.target);
    });
  }, { threshold: 0.1, rootMargin: '0px 0px -30px 0px' });

  singles.forEach(function(id) {
    var el = document.getElementById(id);
    if (el) obs.observe(el);
  });
  if (stepsWrap) obs.observe(stepsWrap);
})();
</script></div></div></div></div></div></div></div></section></div>
