  letter-spacing: 0.22em; text-transform: uppercase; color: #0B5FB7;
}
.so-pt__h2 {
  font-size: clamp(1.9rem, 3vw, 2.7rem); font-weight: 700;
  letter-spacing: -0.04em; line-height: 1.05; color: #0B1A2E;
}
.so-pt__h2 span {
  background: linear-gradient(90deg, #0B5FB7, #3EB2F0);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.so-pt__header-note {
  font-size: 0.95rem; font-weight: 400; line-height: 1.75;
  color: rgb(72,87,112); border-left: 2px solid rgba(9,58,126,0.12);
  padding-left: 1.4rem; align-self: center;
}

/* ── LAYOUT — Karte jetzt 440px statt 280px ── */
.so-pt__layout {
  display: grid;
  grid-template-columns: 440px 1fr;
  gap: 3rem;
  align-items: start;
}

/* ── MAP COLUMN ── */
.so-pt__map-col {
  position: sticky;
  top: 100px;
  opacity: 0;
  transform: translateX(-12px);
  transition: opacity 0.75s ease 0.1s, transform 0.75s ease 0.1s;
}
.so-pt__map-col.so-pt__vis { opacity: 1; transform: none; }

.so-pt__map-wrap {
  background: #fff;
  border: 1px solid rgba(9,58,126,0.08);
  padding: 1.8rem 1.8rem 2rem;
  position: relative;
}
.so-pt__map-wrap::before {
  content: '';
  position: absolute; top: 0; left: 0; right: 0;
  height: 2px;
  background: linear-gradient(90deg, #0B5FB7, #3EB2F0);
}
.so-pt__map-top {
  display: flex; justify-content: space-between; align-items: center;
  margin-bottom: 1.2rem; gap: 1rem;
}
.so-pt__map-label {
  font-family: 'JetBrains Mono', monospace; font-size: 0.54rem;
