  transition: opacity 0.22s;
  display: flex; align-items: center; gap: 0.45rem;
  text-align: right;
  line-height: 1.3;
}
.so-pt__active-partner.so-pt__active-visible { opacity: 1; }
.so-pt__active-partner::before {
  content: ''; width: 5px; height: 5px; border-radius: 50%;
