  transform-origin: center;
  transform-box: fill-box;
}
.so-pt__pin-aura.so-pt__pin-aura--active {
  opacity: 1;
  animation: so-pt-aura-pulse 1.8s ease-in-out infinite;
}
@keyframes so-pt-aura-pulse {
