.so-pt__card:nth-child(7) { transition-delay: 0.40s; }

.so-pt__card:hover { background: #fff; box-shadow: 0 4px 20px rgba(9,58,126,0.08); z-index: 1; }

/* Top-Bar: default gradient blau, bei Hover rot (matched die Karte) */
.so-pt__card::before {
