  transition: background 0.2s, color 0.2s, border-color 0.2s;
}
/* Hover: Chips werden rot (matched die Karten-Pins) */
.so-pt__card:hover .so-pt__location {
  background: rgba(217,52,43,0.06);
  border-color: rgba(217,52,43,0.15);
  color: rgba(217,52,43,0.85);
}
/* DORMED-Card bleibt blau auch bei Hover */
.so-pt__card--highlight .so-pt__location,
.so-pt__card--highlight:hover .so-pt__location {
  background: rgba(62,178,240,0.08);
