<script>
(function() {
  'use strict';

  var svg = document.getElementById('so-pt-svg');
  var activeBox = document.getElementById('so-pt-active');
  var activeLabel = document.getElementById('so-pt-active-label');
  var cards = document.querySelectorAll('.so-pt__card');

  var partnerNames = {
    'jendreyko': 'Medizintechnik Jendreyko',
    'hering': 'Hering Medizintechnik',
    'rehrmann': 'MTG Rehrmann',
    'stuttgart': 'DORMED Stuttgart',
    'seybold': 'Seybold Medizintechnik',
    'schmitt': 'R. Schmitt-Haverkamp',
    'dormed': 'DORMED med. Systeme'
  };

  function clearActive() {
    if (!svg) return;
    svg.querySelectorAll('.so-pt__pin--active, .so-pt__pin-aura--active').forEach(function(el) {
      el.classList.remove('so-pt__pin--active', 'so-pt__pin-aura--active');
    });
    svg.classList.remove('so-pt__map-svg--hover-active');
    activeBox.classList.remove('so-pt__active-visible');
  }

  function activatePartner(partner) {
    if (!svg) return;
    clearActive();

    // DORMED-Card: keine rote Markierung, nur Standard-Anzeige
    if (!partner || partner === 'dormed') return;

    svg.querySelectorAll('[data-partner="' + partner + '"]').forEach(function(el) {
      if (el.classList.contains('so-pt__pin-partner')) {
        el.classList.add('so-pt__pin--active');
      } else if (el.classList.contains('so-pt__pin-aura')) {
        el.classList.add('so-pt__pin-aura--active');
      }
    });

    svg.classList.add('so-pt__map-svg--hover-active');
    activeLabel.textContent = partnerNames[partner] || partner;
    activeBox.classList.add('so-pt__active-visible');
  }

  cards.forEach(function(card) {
    var partner = card.getAttribute('data-partner');
    if (!partner) return;

    card.addEventListener('mouseenter', function() { activatePartner(partner); });
    card.addEventListener('mouseleave', function() { clearActive(); });

    // Mobile: Touch toggles
    var tapActive = false;
    card.addEventListener('touchstart', function(e) {
      if (tapActive) {
        clearActive();
        tapActive = false;
      } else {
        activatePartner(partner);
        tapActive = true;
      }
    }, { passive: true });
  });

  // Scroll-Animationen
  var header = document.getElementById('so-pt-hdr');
  var mapCol = document.getElementById('so-pt-map');
  var grid   = document.getElementById('so-pt-grid');
  var obs = new IntersectionObserver(function(entries) {
    entries.forEach(function(e) {
      if (!e.isIntersecting) return;
      if (e.target.id === 'so-pt-grid') {
        e.target.querySelectorAll('.so-pt__card').forEach(function(c) {
          c.classList.add('so-pt__vis');
        });
      } else {
        e.target.classList.add('so-pt__vis');
      }
      obs.unobserve(e.target);
    });
  }, { threshold: 0.08, rootMargin: '0px 0px -30px 0px' });
  [header, mapCol, grid].forEach(function(el) { if (el) obs.observe(el); });
})();
</script></div></div></div></div></div></div></div></section></div>
